import sys

def main():
    import sys
    s = sys.stdin.read().strip()

    n = len(s)
    count = 0

    for k in range(n):
        t = s[k:] + s[:k]
        first_letter = t[0]
        seen = set()

        for i in range(1, n):
            if t[i] == first_letter:
                seen.add(i)

        if len(seen) == 1:
            count += 1

    probability = count / n
    print(f"{probability:.12f}")

if __name__ == "__main__":
    main()
